CREATE TABLE IF NOT EXISTS accounts ( id TEXT PRIMARY KEY, code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, type TEXT NOT NULL );
CREATE TABLE IF NOT EXISTS journal_entries ( id TEXT PRIMARY KEY, date TEXT NOT NULL, memo TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS journal_lines ( id TEXT PRIMARY KEY, entry_id TEXT NOT NULL, account_id TEXT NOT NULL, debit INTEGER NOT NULL DEFAULT 0, credit INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(entry_id) REFERENCES journal_entries(id) ON DELETE CASCADE, FOREIGN KEY(account_id) REFERENCES accounts(id) );
